function differenceOfDistinctValues(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const answer = Array.from({ length: rows }, () => new Array(cols).fill(0));

  for (let offset = 1 - rows; offset < cols; offset++) {
    const startRow = Math.max(0, -offset);
    const startCol = Math.max(0, offset);
    const length = Math.min(rows - startRow, cols - startCol);

    const above = new Set();
    for (let k = 0; k < length; k++) {
      answer[startRow + k][startCol + k] = above.size;
      above.add(grid[startRow + k][startCol + k]);
    }

    const below = new Set();
    for (let k = length - 1; k >= 0; k--) {
      const row = startRow + k;
      const col = startCol + k;
      answer[row][col] = Math.abs(answer[row][col] - below.size);
      below.add(grid[row][col]);
    }
  }
  return answer;
}

