function differenceOfDistinctValues(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const result = [];
  for (let r = 0; r < m; r++) {
    const line = [];
    for (let c = 0; c < n; c++) {
      const before = [];
      for (let i = r - 1, j = c - 1; i >= 0 && j >= 0; i--, j--) {
        if (!before.includes(grid[i][j])) before.push(grid[i][j]);
      }
      const after = [];
      for (let i = r + 1, j = c + 1; i < m && j < n; i++, j++) {
        if (!after.includes(grid[i][j])) after.push(grid[i][j]);
      }
      line.push(Math.abs(before.length - after.length));
    }
    result.push(line);
  }
  return result;
}

